def fig(src,cap,alt=None):
 return f'<figure class="reveal"><a class="zoom" href="{{ROOT}}assets/{src}" aria-label="Enlarge: {escape(alt or cap,quote=True)}"><img src="{{ROOT}}assets/{src}" alt="{escape(alt or cap,quote=True)}" loading="lazy" decoding="async"></a><figcaption>{cap}<span>↗ Enlarge</span></figcaption></figure>'
def section(k,t,body): return f'<section class="story-section reveal"><div class="section-label">{k}</div><div><h2>{t}</h2>{body}</div></section>'
def p(s): return '<p>'+s+'</p>'
def pair(image,title,body):return '<section class="visual-pair">'+image+'<div class="reveal"><h2>'+title+'</h2>'+p(body)+'</div></section>'
