def footer(r):return f'<footer class="site-footer shell"><div><h2>Let’s talk.</h2><a class="email" href="mailto:bek74@cornell.edu">bek74@cornell.edu</a></div><div class="footer-details"><p>Cornell Information Science · May 2027</p><nav aria-label="Footer"><a href="https://github.com/BerylKoko">GitHub ↗</a><a href="https://www.linkedin.com/in/beryl-koko-28a619245/">LinkedIn ↗</a><a href="{r}assets/beryl-koko-resume.pdf">Résumé ↗</a></nav></div></footer>'
